import { enqueue } from "../jobs/queue.ts";

const DELAYS_HOURS = [24, 72, 168];

export async function scheduleDunning(invoiceId: string, attempt = 0) {
  const hours = DELAYS_HOURS[attempt];
  if (hours === undefined) return markUncollectible(invoiceId);
  await enqueue("charge-invoice", { invoiceId, attempt }, { delayHours: hours });
}

