export async function chargeInvoice({ invoiceId, attempt }: { invoiceId: string; attempt: number }) {
  const paid = await stripe.invoices.pay(invoiceId).catch(() => null);
  if (!paid) await scheduleDunning(invoiceId, attempt + 1);
}

